widget.solution:
import numpy as np
from sklearn.linear_model import Lasso

def first_to_zero(X, y, alphas):
    for a in alphas:
        coef = Lasso(alpha=a, max_iter=10000).fit(X, y).coef_
        zeros = np.flatnonzero(coef == 0)
        if len(zeros) > 0:
            return int(zeros[0])
    return None
